    detail: "「窓がない」という表現は、モナドが外から何かを受け取ったり外へ働きかけたりしないという意味です。では世界の秩序はどう成り立つのか。それを引き受けるのが予定調和で、神が創造の時点ですべてのモナドの内的な展開を調和させている、と説明されます。\n\n各モナドは宇宙全体を自分の視点から表象しているとされます。違うのは表象の明晰さの度合いで、その差が単純なモナドから動物の魂、人間の精神へという階層になります。同じ町を違う場所から眺めると別の眺望になる、という比喩が使われます。\n\n背景には、延長をもつものは無限に分割できるので真に単一なものではありえない、という考えがあります。だから実在の単位は非物質的でなければならない。ここがデカルトの延長実体への批判点であり、モナドが物質的な原子とはまったく別物である理由でもあります。",
