    detail: "見落とされやすいのは、ホッブズの自然状態が歴史上実在した時代の記述ではないという点です。国家がなければどうなるかを論理的に取り出すための思考実験であり、内戦期のイングランドという文脈の下で書かれています。\n\n論証の骨格は三段です。第一に、人間の能力の差はわずかであり、最も弱い者でも策を用いれば最も強い者を殺せる。第二に、そのため誰も安全を確信できず、身を守るには先手を打つのが合理的になる。第三に、この推論を全員が行うため、実際の戦闘がなくても戦争状態が常態化する。\n\nつまり「万人の万人に対する戦争」は、絶えず殴り合っている状態ではなく、いつ襲われてもおかしくないと全員が身構えている状態を指します。ホッブズ自身、雨が降っていなくても降りそうな空模様が続く状態にたとえて説明しています。",
