    detail: "信託という語の選び方が要点です。譲渡なら渡した側に何も残りませんが、信託であれば目的のために預けているにすぎず、目的に反した使い方をされれば取り戻せます。ホッブズの契約構造との違いはここに集約されます。\n\n抵抗権の議論は、名誉革命を擁護するために書かれたと長く考えられてきました。しかしラスレットの研究以降、『統治二論』の主要部分は名誉革命より前、王位継承をめぐる排斥法危機の頃に書かれていたことが定説になっています。事後の正当化ではなく、事前の抵抗の理論だったわけです。\n\nこの論理はアメリカ独立宣言に流れ込みます。政府が生命・自由・幸福追求の権利を守らないとき、人民はこれを改廃できる、という一節はロックの議論をほぼそのまま踏襲したものです。",
