    detail: "ルソーの議論は二冊にまたがっています。『人間不平等起源論』が自然状態から不平等がどう生じたかを描き、『社会契約論』がではどういう政治体なら正当かを論じる。前者だけ読むと文明批判の人に見え、後者だけ読むと国家設計の人に見えるので、両方の関係を押さえておく必要があります。\n\n「自然に帰れ」はルソーの言葉ではありません。ルソー自身、自然状態はもはや存在せず、おそらく一度も存在しなかったかもしれないと述べており、戻れるとも戻るべきだとも言っていません。あくまで現在の人間から社会に由来する部分を差し引いたらどうなるかを考えるための仮構です。\n\n鍵になるのが自己愛と利己心の区別です。自己愛は自分の生存を求める自然な感情ですが、利己心は他人との比較のなかで生じ、他人より上に立ちたいという欲求になります。社会が発達して人が互いを見比べるようになったときに後者が生まれ、不平等と支配が始まる、というのがルソーの見立てです。",
