    answer: 1,
    explanation: "各人の私的利益を足し合わせたものは全体意志であり、一般意志とは区別されます。一般意志は共通利益に向かうものとされ、自分もその形成に参加しているからこそ、それに従うことが自由と両立するという議論になります。この概念は全体主義的だという批判も繰り返しなされてきました。",
    detail: "一般意志への批判は古くからあり、代表的なものが二つあります。ひとつは、誰が一般意志を判定するのかという手続きの問題です。多数決の結果と一般意志は同じではないとルソー自身が述べているので、多数派が誤ることもありうる。各人が自分の利益から抱く特殊意志は、集まっても全体意志にしかならず、一般意志とは別のものだとされます。ではその誤りを誰が指摘するのか。ここに、少数の指導者が「これこそ本当の一般意志だ」と宣言する余地が生じます。ルソー自身は、人民に法を与える特別な役割として立法者を置きますが、立法者は権力も投票権ももたず説得するだけの存在とされ、難点はかえって際立ちます。\n\nもうひとつが、一般意志に従わない者は「自由であるよう強制される」という一節です。これを全体主義の萌芽と読む立場（バーリンやタルモンが代表的）と、共同体の自己立法という文脈で読めば穏当だとする立場が対立してきました。\n\nさらにルソーはフランス革命、とくにジャコバン派との関連で語られることが多いのですが、その影響の実際の大きさをめぐっても評価が割れています。",
