      note: "一般意志を全体主義の萌芽と読むか（タルモン『全体主義的民主主義の起源』1952年、バーリン）、共同体の自己立法として読むか（クランストン、マクレランドら）で対立が続いている。争点は「自由であるよう強制される」（『社会契約論』第一篇第七章）の解釈と、誰が一般意志を判定するのかという手続き。設問へ: この対立は評価をめぐるもので、設問が問う一般意志と全体意志の区別自体はどちらの陣営も争っていない。四択は成立している。 選択肢の均等化: 正解末尾の説明句「私的利益の総和である全体意志とは区別される」を削除（explanation に既述）。あわせて誤答1つを肉付け。四択の成立を確認済み。2.29倍→1.09倍。 鍵語の追補: ルソーの立法者を detail に足した。478問のどこにも出ておらず、一般意志を誰が判定するのかという論点の隣にあたるため、この問題が置き場所として適当。 2026年9月11日。"
