    detail: "束説には、ヒューム自身が納得していなかった形跡があります。『人間本性論』の付録で、知覚を束ねているものについて自分の説明では満足できないと率直に書いており、この告白は現在も研究上の論点です。\n\n論点は人格の同一性です。昨日の自分と今日の自分が同じだと言えるのはなぜか。ヒュームの答えは、記憶と因果の連鎖によって連続しているように見えるからであり、その連続性は想像力が作り出した虚構だ、というものです。実体としての自我があるからではありません。\n\n仏教の無我との類似がよく指摘されますが、ヒュームが仏教を知っていたかどうかについては確証がなく、影響関係は不明です。似た結論に別の道筋で辿り着いた例として扱うのが無難でしょう。デカルトが不動の出発点として立てた「私」が、経験の側から掘り崩される場面として読むと、近代哲学の流れのなかでの位置がはっきりします。",
