    detail: "「独断のまどろみから覚まされた」は『プロレゴメナ』の一節です。ただしカントがヒュームのどこに、どこまで覚まされたのかは、研究上ずっと議論されてきた論点でもあります。\n\nカントの応答の骨子はこうです。ヒュームは正しく、因果の必然性は経験から取り出せない。しかし因果を使わずに経験は成立しない。ならば因果は経験から来るのではなく、経験を組み立てる側の枠組みとして先にあると考えるほかない。\n\nこれが「アプリオリな総合判断はいかにして可能か」という問いの立て方であり、コペルニクス的転回と呼ばれる発想の転換です。対象に認識が合わせるのではなく、認識の枠に対象が合わせられて現れる、と向きを逆にしました。ただし「コペルニクス的転回」はカント自身の語ではありません。第二版序文にあるのは「コペルニクスの最初の着想」で、転回や革命という言い方は後世の呼称です。\n\nただしこの解決には代償があります。因果が私たちの枠組みだとすると、その枠を通さないありのままの姿には手が届かないことになる。これが物自体の不可知という帰結で、次の世代からの批判の的にもなりました。",
