    detail: "アウフヘーベンという語をヘーゲルが選んだ理由は、ドイツ語の日常語がすでに正反対の意味を併せもっていたことにあります。取り除くという意味と、しまっておくという意味の両方があり、そこに高めるという含みが加わる。ヘーゲル自身が、言語がすでに思弁的な精神をもっている例としてこの語を挙げています。\n\n具体例として最も知られているのが主人と奴隷の弁証法です。承認をめぐる闘争のすえ主人と奴隷の関係が成立しますが、主人は奴隷に承認されても相手を対等と認めていないので満たされず、奴隷のほうは労働を通じて対象を形づくることで自立していく。当初の関係がそのまま逆転していくこの運動が、止揚の実例として読まれてきました。\n\nもうひとつの鍵語が規定的否定です。何かを否定した結果は空虚な無ではなく、特定の内容をもった次の規定になる。だから運動が先へ進む。ここが「単に否定する」批判との違いです。",
