    detail: "テキストの扱いに注意が要る箇所です。『歴史哲学講義』はヘーゲル自身が刊行した著作ではなく、講義を聴いた学生のノートをもとに編集されたものです。どこまでヘーゲル本人の言葉かについては慎重さが求められ、現在は複数の年次の講義録を区別して読む研究が進んでいます。\n\n内容の骨子は、世界史とは自由の意識が進展していく過程だ、というものです。一人だけが自由な段階から、一部の者が自由な段階を経て、すべての者が自由であることが知られる段階へ進む、と語られます。個人の情熱はその進行を担う素材として使われるにすぎない、というのが理性の狡知です。\n\nこの歴史観には強い批判が向けられてきました。結果として起きたことを理性的だと追認する勝者の歴史観になりかねない点、そして非ヨーロッパ地域を歴史の初期段階として位置づける記述が含まれる点です。この二つは切り離せない問題として、現在も論じられています。",
