    detail: "翻訳の問題が理解を妨げている典型例です。エウダイモニアは「良く生きていること」に近く、本人がそう感じているかどうかとは独立に成り立ちます。一方ベンサムの幸福は本人が感じる快苦そのものなので、本人の申告がすべてです。日本語ではどちらも幸福と訳されるため、同じことを論じているように見えてしまいます。\n\nこの対立は現代にも引き継がれています。幸福を本人の主観的な満足で測る立場と、健康や教育や人間関係といった客観的な項目のリストで測る立場の対立です。政策の場面では、国民の幸福度を主観的な調査で測るのか、それとも生活の実質的な条件で測るのか、という形で現れます。\n\nセンのケイパビリティ論は、この論争にもうひとつの角度を持ち込みました。満足しているかどうかではなく、その人が実際に何をなしうるかで見るという考え方で、アリストテレス的な発想の現代的な展開として位置づけられます。",
