    detail: "ロックが誰を批判していたのかは、実は研究上の論点です。デカルトを名指ししているわけではなく、当時イングランドで生得原理を語っていた別の論者たちが標的だったとする見方もあります。デカルト自身、生得観念とは生まれたときから意識にあるという意味ではなく生得的な傾向のことだと説明しており、ロックの批判がその立場に届いているかには疑問が残ります。\n\nこれに正面から応答したのがライプニッツの『人間知性新論』です。感覚のうちになかったものは知性のうちにない、という経験論の標語に対し、「知性それ自身を除いては」と付け加えました。経験を受け取る側の構造そのものは経験から来ない、という反論で、後のカントに通じる論点です。\n\nこの争点は20世紀に再燃しました。チョムスキーが、子どもの言語習得の速さを説明するには生得的な言語能力を認めるほかないと主張し、経験論的な学習理論と論争になっています。哲学史のなかで終わった話ではありません。",
