    answer: 1,
    explanation: "経験から得られるのは色や形といった性質だけですが、それらが単独で浮いているとは考えにくい。そこで支え手を想定せざるをえないものの、その支え手自体は経験に現れないので中身が分からない、という結論になります。「それが何かは知らないが何か」という有名な言い回しがここから出ます。",
    detail: "この宙ぶらりんな結論は、経験論の枠内で実体という伝統的な概念を扱おうとしたときに必然的に生じる困難を示しています。合理論者たちが定義から実体の性質を導き出したのとは対照的に、経験から出発すると実体には手が届きません。\n\nここから解体が進みます。バークリーは、支え手など想定する必要はなく知覚されることが存在することだとして物質的実体を消しました。さらにヒュームが、同じ論法を精神の側にも適用して精神的実体も否定します。ロックが残した「何だか分からないもの」が、二段階で削り落とされていく流れです。\n\n一次性質と二次性質の区別も同じ議論のなかにあります。形や大きさや運動は物の側にあるが、色や音や味は知覚する側で生じる、という区別です。バークリーはこの区別自体を攻撃し、一次性質とされたものも結局は知覚されたものにすぎないと論じました。近代の認識論が、外界をどこまで信頼できるかという問いへ収束していく過程が見て取れます。",
