    detail: "倫理の基礎づけの仕方がここで決まります。善悪はあらかじめ定まっているのではなく、自分の存在の維持と増大に役立つものが善、妨げるものが悪と定義されます。価値を外から与えられた規範ではなく、存在の側から捉え直す構図です。\n\nホッブズの自己保存と似ていますが、方向が違います。ホッブズでは自己保存が他者との争いを生み、それを抑えるために主権が必要になる。スピノザでは、理性に導かれた人間どうしは本性が一致するので、むしろ協力するほうが各自の力を増す、とされます。同じ出発点から正反対の社会像が出てくる例です。\n\nコナトゥスは後の思想に二通りの形で引き継がれます。ニーチェは『善悪の彼岸』第13節で自己保存を余計な目的論的原理と呼び、スピノザの名を挙げて退けました。力への意志は継承ではなく対抗です。他方ドゥルーズの読解は再評価にあたり、現代思想でも参照され続けています。",
