    detail: "四つのアンチノミーが挙げられます。世界の時間的な始まりと空間的な限界、単純なものへの分割、自由な原因性の有無、必然的存在者の有無です。前二つと後二つでは解決の仕方が違い、前者はどちらも偽、後者は観点を分ければ両立しうる、とされます。\n\nとくに第三アンチノミーは自由の問題に直結します。すべてが自然の因果に従うという命題と、自由による原因性があるという命題が衝突する。カントは、現象としては前者が、叡智的な存在としては後者が成り立つとして両立させます。自律としての自由の議論はここに支えられています。\n\nアンチノミーの発見はカント自身にとって決定的な経験だったようで、1798年のガルヴェ宛書簡では、これが独断のまどろみから自分を目覚めさせたと書いています。ただし『プロレゴメナ』の序文では、目覚めさせたのはヒュームの想起だと書いており、二つの証言は食い違ったままです。どちらにせよ、理性を批判する必要があるという着想の出どころのひとつではあります。",
