    detail: "市民社会の分析が現代から見て興味深いところです。ヘーゲルは、市民社会が富の集中と貧困層の発生を同時に生み出し、それが自らの資源では解決できないと指摘しています。この認識はマルクスに直接引き継がれました。\n\n国家の位置づけは長く論争の的です。国家を人倫の完成とする議論は、個人を国家に従属させる全体主義的な主張だと批判されてきました。ポパーはヘーゲルを全体主義の思想的源流のひとりに数えています。\n\n他方で、ヘーゲルの国家は市民社会の自由を否定するのではなく、それを前提として包み込むものだ、とする読みも有力です。彼が擁護したのは立憲君主制であり、当時のプロイセンの現状追認だったのか改革的な提案だったのかも論じ続けられていますが、両論が対等に競っているわけではありません。ポパー流に権威主義の擁護として読むのは誤りだとする論者が今日では多数で、改革期の目標に与した提案と見る読みのほうが優勢です。ただしそれで決着したわけではありません。テキストが書かれた政治状況とあわせて読む必要がある箇所です。",
