    answer: 1,
    explanation: "何かを説明するには、それが何でできているか（質料因）、何であるか（形相因）、何によって生じたか（作用因）、何のためにあるか（目的因）の四つが必要だとされます。彫像なら青銅、像の形、彫刻家、そして飾られる目的にあたります。",
    detail: "一番目は紛らわしい選択肢です。可能態と現実態はアリストテレスの重要な概念ですが、四原因のうちには含まれません。質料と形相の関係を別の角度から捉えた対概念であり、混同されやすいところです。\n\n近代科学が捨てたのは目的因でした。自然のものが何かのために存在するという説明を追放し、作用因だけで自然を記述する方針に切り替えたのが機械論的自然観です。デカルトやベーコンはこの点でアリストテレスを明確に否定しています。\n\nただし目的論的な説明は完全に消えたわけではありません。生物学では、心臓は血液を送るためにあるという言い方が今も機能を語る形で使われています。この種の説明が本当の目的論なのか、それとも自然選択によって説明し直せるのかは、科学哲学の論点であり続けています。",
