    detail: "三番目の選択肢はアリストテレス以来のスコラ的な魂の段階説で、まさにデカルトが否定したものです。植物的な魂、感覚的な魂、理性的な魂という区分を捨て、精神をもつかもたないかの二分に切り替えたところがデカルトの新しさでした。\n\n四番目はベンサムの立場です。同じ動物の問いに、デカルトは理性の有無で、ベンサムは苦痛の有無で答えます。基準を変えると線の引かれる場所が変わる典型例になっています。\n\nこの動物機械論は当時から批判が多く、生体解剖への抵抗感とあわせて論争になりました。ヴォルテールは、犬が飼い主を喜んで迎える様子を挙げてデカルトを皮肉っています。心をもつのは誰かという問いは、現在では動物の意識や人工知能をめぐる議論として続いています。",
