    detail: "一番目のような極端な偶然論をバーリンが主張したわけではありません。歴史に傾向や構造があること自体は否定せず、それを個人の行為を消し去るほど強い決定論に仕立てることを問題にしています。\n\n背景には、価値多元主義と同じ関心があります。歴史に単一の法則を読み込む思考は、すべての問いに唯一の答えがあるという一元論の一形態であり、その帰結として現在の犠牲を歴史の必然として正当化する議論が出てくる、という警戒です。\n\nこの論点はE.H.カーとの論争としても知られています。歴史における個人の役割をどう評価するか、歴史家は道徳的判断を下すべきかという問いは、歴史学の方法論の古典的な争点であり続けています。",
