    detail: "複数投票制の提案は、現在から見ればもっとも受け入れがたい部分です。政治的平等の原則と正面から衝突しますし、教育程度をどう測るのかという問題もあります。ミルの自由主義がエリート主義的な性格を帯びていた例として引かれます。\n\nただしミル自身は、これを財産による制限の代替として提案しています。当時の選挙権は財産による制限が当然でしたから、それを教育に置き換え、かつ女性を含む普通選挙へ広げるという文脈にありました。時代の位置づけを踏まえないと評価を誤ります。\n\n比例代表制への支持のほうは、現代の選挙制度論に直接つながっています。多数派が議席を独占する制度では少数意見が政治過程から消えてしまうという問題意識は、いまも生きています。",
