    detail: "一番目はヘーゲルの立場で、ショーペンハウアーが激しく敵視したものです。同じベルリン大学でヘーゲルと同じ時間に講義を設定して惨敗した逸話が伝えられており、著作のなかでも罵倒に近い言葉を浴びせています。\n\n意志という語には注意が要ります。何かを意図する意識的な意志ではありません。植物が伸びること、結晶が形をとること、重力そのものまで含む、目的なき衝動を指します。日常語からずれた使い方をしているところが、この概念の分かりにくさの原因です。\n\n個体化の原理という論点も重要です。時間と空間は表象の側の形式なので、それを取り払った意志そのものは一つであり、個体に分かれていない。この発想はウパニシャッドの影響を受けており、ショーペンハウアーは西洋哲学者として早い時期にインド思想を本格的に取り込んだ人物でもあります。",
