    detail: "他の選択肢はいずれも別の哲学者の枠組みです。三番目はヘーゲルの用語法、四番目はスピノザの三種の認識。似た三段構成が並ぶので混ざりやすいところです。\n\n重要なのは、この移行が連続的な発展ではないことです。ヘーゲルの弁証法のように前段階が高い段階へ引き上げられるのではなく、断絶を跳び越える決断が要る。キルケゴールはこれを質的弁証法と呼び、量的な移行と区別しました。\n\n著作の形式もこれに対応しています。『あれか、これか』では美的段階と倫理的段階がそれぞれ別の人物の文書として並置され、著者は編者を装うだけで結論を与えません。読者自身が選ばなければならない、という仕掛けです。多数の偽名を使い分けたのも同じ理由からで、思想を体系として提示しないための工夫でした。",
