    detail: "この転倒という比喩が正確に何を意味するのかは、長く議論されてきました。観念を物質に置き換えれば済むという単純な操作なのか、それとも方法そのものの組み替えが必要なのか。ヘーゲルの弁証法から合理的な核だけを取り出せるのかという問いは、20世紀のマルクス主義における中心的な論点でした。\n\n四番目の選択肢は誤りですが、実は無視できない論点でもあります。後期マルクスの経済分析に弁証法がどこまで実質的に働いているかについては、アルチュセールをはじめとして疑問を呈する読みが存在します。\n\nなお、正反合という定式はヘーゲル自身の用語法ではないという指摘が広く共有されています。マルクスの弁証法を説明する際にもこの図式が使われがちですが、同じ注意が必要です。",
