    detail: "この批判が『正義論』の出発点になっています。功利主義が長く支配的だった英語圏の政治哲学に対し、それに代わる体系的な選択肢を提示するという課題設定です。実際この本の刊行によって、政治哲学という分野そのものが復活したと言われます。\n\n無知のヴェールという装置は、この批判と対応しています。自分が誰か分からない状態で選ばせることで、他人の犠牲を前提とする原理を選べなくする。誰の立場に置かれても受け入れられるかを問う設計です。\n\n功利主義の側からの応答もあります。ハーサニは、無知のヴェールの下で確率を考慮すれば期待効用の最大化が選ばれ、結局は功利主義的な原理に至ると論じました。またミルの質的功利主義や規則功利主義は、素朴な総和主義とは違うという反論もあります。",
