      kind: "ai_web", label: "ウェブ照合済み",
      choicesOk: "ok",
      note: "設問へ: 社会全体の総和を最大化する発想が人格の別個性を真剣に受け止めていないという批判は『正義論』冒頭の通りで、誤答一番目は技術的批判、三番目は動機説への誤解、四番目は方向が逆の批判。四択は成立している。 事実の確認: 個人内部での損得の調整を社会に持ち込むという構図、およびそれが人と人が別個の存在であるという事実を無視するという論点は、q035（ベンサムの快楽計算）の detail にも同じ形で書かれており、二問の記述は揃っている。q035 は検証済みで、note にこの批判が正確だと記録されている。 設計の記録: detail が「無知のヴェールという装置は、この批判と対応しています」と、批判と設計の対応関係を示している。批判が先にあり装置が後から来るという順序が明確で、q144（原初状態）の記述とも噛み合う。 事実の確認: ハーサニの反論（無知のヴェールの下で確率を考慮すれば期待効用最大化が選ばれ功利主義的原理に至る）は q144 の note に書いた1975年の論文の内容と一致する。ミルの質的功利主義や規則功利主義が素朴な総和主義とは違うという反論も、q111・q119 の記述と食い違わない。 選択肢の均等化: 正解の説明句を削り（解説側に既述）、誤答を型に揃えて肉付けした。四択の成立を確認済み。 2.82倍→1.17倍。 あわせて type を compare から single に修正（正解が二人の立場の対比になっていないため）。",
