    detail: "有名な論証がウィルト・チェンバレンの例です。どんな分配から出発しても、人々が自発的に対価を払ってスター選手の試合を見に行けば、その選手のもとに富が集まり、当初の型は崩れます。型を維持しようとすれば、人々の自発的な取引に絶えず介入し続けねばならない。自由は型を掘り崩す、という主張です。\n\nこの議論から最小国家の擁護が導かれます。国家の正当な機能は暴力や詐欺からの保護と契約の執行に限られ、再分配のための課税は強制労働に等しい、という強い主張です。\n\n批判としては、そもそも取得における正義が成立しているのかという点が挙げられます。現実の所有の来歴を遡れば征服や収奪が現れる以上、矯正の原理を厳密に適用すると大規模な再分配が必要になるのではないか、という指摘です。ノージック自身、この原理を十分に展開できていないと認めています。",
