    detail: "両者はハーバードの同僚でした。『アナーキー・国家・ユートピア』は『正義論』の三年後に刊行され、直接の応答として書かれています。同じ問題設定を共有しながら正反対の結論に至る好例です。\n\n対立の根は、才能をどう扱うかにあります。ロールズは生まれつきの才能の分布を道徳的に恣意的なものとし、その分布を共有資産とみなして、そこから生じる利益を分かち合おうとします。ノージックは、それでは人を他人の目的のための手段として扱うことになると反論し、カントの定式を自分の側に引き寄せます。\n\n興味深いことに、ノージックは後年、自らのリバタリアニズムがあまりに厳格だったと述べています。ただしどこまで立場を変えたのかについては解釈が分かれており、撤回とまでは言えないという読みもあります。",
