    detail: "この批判は、正義の基準についての議論であると同時に人格観についての議論です。何が正しいかを、何が善い生き方かという問いから切り離せるのか。自由主義は善に対する正の優先を掲げますが、サンデルはその分離自体が成り立たないと論じます。\n\nロールズ側の応答は、原初状態は人格の形而上学的な描写ではなく、正義の原理を選ぶための装置にすぎない、というものです。『政治的リベラリズム』における政治的構想への限定は、この種の批判への応答という側面をもちます。\n\n共同体主義には他にマッキンタイア、テイラー、ウォルツァーらがいますが、主張は一様ではありません。サンデル自身は共同体主義という呼び名を必ずしも好まず、共同体の慣習が常に正しいわけではないと明言しています。多数派の価値の押しつけになるという懸念は、この立場に向けられる主要な批判です。",
