      note: "設問へ: 抑圧によって意識から締め出され抵抗を受けるために通常の想起では意識に上らないが、症状や夢や失錯行為として現れる領域という規定は精神分析の無意識の通りで、誤答一番目は前意識との混同、三番目は睡眠時の状態への還元、四番目は脳部位への還元。四択は成立している。 設計の記録: explanation が「努力すれば思い出せるものは前意識と呼ばれ、無意識とは区別されます」と、誤答一番目との差を明示している。無意識が長い精神分析を経なければ意識の前面へもたらせないものであり、単に今そのとき意識にない材料とは違うという整理は資料と一致する。無意識を記憶の倉庫ではなく力の働いている場として捉えるという説明も、抑圧という機制の理解として正しい。 事実の確認: 三度目の打撃という位置づけは1917年の論文「精神分析の途上の一困難」にある。人類の普遍的な自己愛は科学の研究によって三度の重い打撃を受けたとされ、コペルニクスによる宇宙論的打撃、ダーウィンによる生物学的打撃、そして精神分析による心理学的打撃、すなわち自我は自分の家の主人ですらないことの証明、という順で挙げられる。detail の記述はこの通り。 事実の確認: ポパーの批判（精神分析はあらゆる可能な事態と両立するため反証されえず、その意味で科学ではない）も資料どおりで、ポパー自身それが精神分析から一切の価値を奪うわけではないとしている点も、detail の「影響の大きさは疑いようがない」という書き方と衝突しない。 選択肢の均等化: 正解の説明句を削り（解説側に既述）、誤答を型に揃えて肉付けした。四択の成立を確認済み。 2.57倍→1.32倍。 選択肢の均等化: 正解の説明句を削り（解説側に既述）、誤答を型に揃えて肉付けした。四択の成立を確認済み。 1.32倍→1.22倍。",
