    detail: "三番目はラカンの三界、四番目はキルケゴールの実存の三段階で、いずれも別の枠組みです。三分割の図式が複数あるので、誰のどの理論かを取り違えやすいところです。\n\n重要なのは、自我のかなりの部分も無意識的だとされる点です。防衛のはたらきは本人に自覚されません。だから第二局所論は第一局所論を置き換えるものではなく、別の切り口を重ねたものと理解されます。\n\n超自我は、エディプス・コンプレックスの帰結として親の禁止が内面化されたものとされます。カントの道徳法則が理性の要請だったのに対し、ここでは道徳が発生の過程から説明されます。ニーチェの系譜学と同じく、価値の起源へ遡る手つきが働いています。",
