    detail: "この分析はデカルト的な世界像への批判になっています。まず眼前に物体があり、それを主観が認識するという構図は、実は日常から派生した二次的な態度にすぎない。壊れて使えなくなったときの現れ方を、世界の本来のあり方だと取り違えている、という指摘です。\n\n道具は単独では存在しないとも述べられます。金槌は釘と、釘は建材と、建材は住むことと結びついており、その全体の連関のうちではじめて道具でありうる。この連関の広がりが世界と呼ばれます。\n\nこの議論は現象学の外へも影響しました。人工知能研究では、ドレイファスがこの分析を用いて、世界を表象の集合として扱う初期の方針の限界を論じています。デザインや認知科学の領域でも参照され続けている分析です。",
