    detail: "有名なのが末尾の一節で、人間は最近の発明であり、やがて波打ち際の砂に描かれた顔のように消え去るだろう、と述べられます。人間という概念そのものが近代のエピステーメーの産物であり、永遠のものではないという含意です。\n\nこの主張は人間の終焉として大きな反響を呼び、実存主義的なヒューマニズムへの決別として受け取られました。サルトルは強く反発しています。\n\nクーンのパラダイム論と似た構造をもつとよく指摘されます。ほぼ同時期に別々の場所で、知の断絶を扱う概念が現れたことになります。ただしフーコーの関心は科学の合理性の説明ではなく、知と権力の絡み合いを歴史的に暴くことにあり、狙いは異なります。フーコーはこの手つきを知の考古学と呼び、思想の連続的な発展を追うのではなく、断絶を含む知の配置を掘り起こす方法として定式化しました。",
