      note: "史実のソクラテスをどこまで辿れるかというソクラテス問題は決着していない（プラトン、クセノフォン、アリストパネスで像が異なる）。また「無知の知」という言い方自体はプラトンの原文にある語ではなく日本語圏で定着したもので、クザーヌスの docta ignorantia を経由したとする説明もある。設問へ: 設問が「いわゆる」と限定しており、正解二番目は『弁明』21d の内容（相手は知らないのに知っていると思い、自分は知らないので知っているとも思わない）に対応する。四択は成立している。 選択肢の均等化: 正解の説明句を削り（解説側に既述）、誤答を型に揃えて肉付けした。四択の成立を確認済み。 2.00倍→1.21倍。"
