    detail: "一番目は限界効用理論の考え方で、ほぼ同時期に別の経済学者たちが展開した立場です。労働価値説と効用価値説の対立は、経済学史の大きな分岐点になりました。現在の主流派経済学は後者の系譜にあります。\n\nマルクスの議論はリカードら古典派経済学を引き継いでいます。ただし、労働そのものではなく抽象的人間労働という社会的な形態を価値の実体とした点、そして労働力という商品を区別した点が独自の一歩です。\n\n労働価値説の妥当性は長く論争されてきました。価値から価格への変換をめぐる転形問題は未解決の難問とされ、この理論を放棄したうえでマルクスの分析を活かそうとする立場も生まれています。理論の当否と、資本主義の運動を捉える枠組みとしての有効性は、分けて論じられることが多い論点です。",
