    detail: "一番目の安く買って高く売るという説明を、マルクスは明確に退けています。流通の場面だけを見ると、誰かの利得は誰かの損失にすぎず、社会全体としては価値が増えません。増殖の秘密は流通ではなく生産の場面にある、というのが論の運びです。\n\nだから搾取は、不当な取引や詐欺によって起きるのではありません。すべてが公正な等価交換として行われながら、なお剰余が生じる。そこがこの分析の要点であり、道徳的な告発とは異なる水準にあります。\n\n剰余価値を増やす方法は二つに分けられます。労働時間そのものを延ばす絶対的剰余価値と、生産性を上げて必要労働時間を短縮する相対的剰余価値です。機械の導入や分業の展開が後者に対応し、技術革新が資本の論理から要請される仕組みが説明されます。",
