    detail: "一番目は分析判断の説明で、まさに対比されるものです。この二分法自体はライプニッツやヒュームの区別を踏まえたもので、カントはそこに第三の区分を加えたことになります。\n\n例として挙げられるのは、七と五を足すと十二になるという算術の判断や、直線は二点間の最短であるという幾何学の判断です。十二という概念は七と五の概念のうちに含まれていない、というのがカントの主張ですが、この分析には後から異論も出ています。\n\n20世紀にこの区分は大きな批判を受けました。フレーゲやラッセルは数学を論理に還元しようとし、論理実証主義はアプリオリな総合判断の存在そのものを否定します。さらにクワインは、分析と総合の区別自体が根拠をもたないと論じ、経験主義の二つのドグマとして批判しました。",
