    detail: "この論点はエクリチュール論と一体です。書かれたものは送り手を離れて流通し、誰が受け取るか分からない。その不確実さは事故ではなく、記号が記号であるための条件だ、というのがデリダの一貫した主張でした。\n\n『絵葉書』の冒頭には、中世の写本に描かれたソクラテスとプラトンの図版が置かれています。ソクラテスが書き、プラトンがその背後に立つという、通常の順序が転倒した絵です。誰が誰に何を送ったのかという系譜そのものが揺らぐ、という仕掛けになっています。\n\n日本語圏では、東浩紀の『存在論的、郵便的』を通じてこの主題が広く知られました。デリダの仕事を否定神学的な系列と郵便的な系列に分けて読む整理は影響力をもちましたが、これは東による読解の枠組みであって、デリダ自身がそう分類したわけではありません。この区別を前提に議論する際は、その点を踏まえておく必要があります。",
