    detail: "推論か直観かという古典的な論点があります。ゆえにという語があるため三段論法に見えますが、それなら考えるものは存在するという大前提が先に必要になり、その前提自体が疑いえないと言えるのかが問題になります。デカルト自身は『省察』に付された第二答弁で、三段論法によって思考から存在を導いているのではなく、精神の単純な直観によって認められるのだと述べています。\n\n確保される範囲も論点です。疑いえないのは、いま思考が行われているということまでではないか。それを担う実体としての私まで一挙に取り出せるのか。この点をヒュームが束説によって突き、リヒテンベルクは、稲光がすると言うのと同じように、それが考えると言うべきだと述べました。\n\n一番目の選択肢は日常的な連想としては自然ですが、コギトの主張ではありません。ここで言われているのは人間の本質ではなく、疑いえない出発点の確保です。",
