    detail: "この区別はガリレイやボイルにも見られるもので、ロックの独創ではありません。測れるものを実在の側に置き、感覚的な質を主観の側に振り分けるという、近代科学の方針を認識論として整理したものです。\n\nバークリーはこの区別を攻撃しました。形や大きさもまた見え方によって変わるのだから、一次性質だけを物の側に置く根拠はない。そう論じて、物質的実体そのものを退けます。ロックが残した区別の不安定さを突いた批判です。\n\nこの論点は現在も生きています。色が物にあるのか脳にあるのかという問いは、心の哲学における感覚の質をめぐる議論に直結します。近代の始まりに引かれた線が、いまだに引き直され続けていることになります。",
