    detail: "三番目のような読みは、反精神医学の潮流と結びついて広まりました。フーコー自身は狂気が実在しないとは述べておらず、それがどう分節され扱われてきたかを問題にしています。ただし当時の運動に影響を与えたことは確かです。\n\nデリダとの論争が有名です。デリダは、デカルトが狂気を排除したというフーコーの読解を批判し、テクストの読み方をめぐって応酬が続きました。同じ世代の二人が正面から衝突した事例として知られています。\n\n歴史学の側からは実証面の批判もあります。大監禁の規模や時期について、資料の扱いが粗いという指摘です。それでもこの著作は、理性の歴史をその外部から問うという方法を打ち立てたものとして評価されています。",
