    detail: "一番目はヘラクレイトス、四番目はプロタゴラスの立場で、いずれもパルメニデスと対極にあります。感覚に現れる変化を、真実在ではなく思い込みの側に置いたのがパルメニデスの一歩です。\n\n断片には、思考することとあることは同じである、という一節があります。思考できるものだけが存在しうるという主張で、以後の存在論の出発点に置かれてきました。またあるものは分割されず、全体としてひとつであるとも述べられ、この一性が後の一者の思想へ受け継がれます。\n\n弟子とされるゼノンの逆説は、この立場の擁護として提出されたと考えられています。運動を認めると矛盾が生じることを示すことで、運動を否定する師の主張を支えるという構図です。またプラトンは『ソフィスト』において、あらぬものにも何らかの意味であることを認めなければ議論が成り立たないと論じ、これを父殺しと呼びました。",
