    detail: "この問い自体はライプニッツに由来します。十分理由律から、なぜ無ではなく何かがあるのかという問いが立てられました。ライプニッツはそこに神の選択という答えを置きますが、ハイデガーは答えではなく問いそのものを取り戻そうとします。\n\n三番目はカントの三つの問いのひとつで、認識の可能性を問うものです。ハイデガーからすれば、認識論の問いは存在の問いを飛ばして先へ進んでしまっている。何が知りうるかの前に、あるとはどういうことかがある、という順序の主張です。\n\nこの問いに答えが与えられているわけではありません。むしろ問いを問いとして立てること自体が課題とされます。答えを出さないという構えを、思考の深まりと見るか、内実の乏しさと見るかで評価が分かれてきました。",
