    detail: "四番目は言い過ぎですが、ハイデガー自身の語り口がそう読ませる面はあります。存在忘却という言い方は、西洋哲学の全体が問いを取り逃がしてきたという構図を描くため、先行者の仕事が過小に見えることがあります。\n\n実際には、彼の初期の講義の多くがアリストテレス読解に充てられています。現存在の分析に用いられる道具や配慮といった概念も、アリストテレスの実践的な知の分析から引き出されたものだと指摘されています。\n\n存在論的差異という主張の眼目は、存在者について語ることと存在そのものを問うことの区別にあります。この区別を立てたうえで、伝統的な形而上学は前者に終始してきたと診断される。批判の妥当性は論じられ続けていますが、問いの立て方そのものが20世紀の哲学に与えた影響は大きなものでした。",
