    detail: "この区別が、言語学の対象を確定するための操作でした。当時の言語学は語の変遷を追う歴史的な比較が主流で、体系そのものを記述するという発想が確立していませんでした。共時態を独立した対象として立てたことが、構造言語学の成立を画します。\n\n三番目はラングとパロールの区別で、これも重要な対概念です。ソシュールの講義には二分法が複数出てくるため、どの区別がどれかを取り違えやすいところです。\n\nこの方針は同時に、批判の的にもなりました。体系を優先することで、実際の使用や変化や社会的な差異が視野から外れます。後の社会言語学や語用論は、まさにその外された部分を扱う方向へ進みました。",
