    detail: "この原理から、言語の要素どうしの関係が二つに分けられます。実際に並べられた要素どうしの連辞的な関係と、その位置に置きえた他の候補との連合的な関係です。文のなかにある語は、隣の語との関係と、選ばれなかった語との関係の両方によって意味をもつことになります。\n\nこの二軸の区別は、後の分析で広く用いられました。ヤコブソンはこれを隠喩と換喩の対に結びつけ、ラカンはさらにフロイトの圧縮と置換に対応させます。ソシュールの技術的な区別が、思想の言語へ移されていった経路です。\n\nなお線条性の原理には批判もあります。イントネーションや強勢のように、同時に重なる要素が音声にも存在するためです。原理の適用範囲をどう考えるかは、言語学の内部で議論されてきました。",
