    detail: "この枠組みは近代の自然法論に受け継がれました。ホッブズも自然法を語りますが、根拠がまったく違います。アクィナスにおいて自然法は神の理性への分有ですが、ホッブズにおいてはそれぞれの自己保存という利害から理性が導く規則です。同じ語で土台が入れ替わっています。\n\n一番目は法実証主義の立場で、ベンサムやオースティンの系譜にあたります。不正な法も法であるかという論点は、この対立の核心です。20世紀にはハートとフラーの論争として、ナチス時代の法をどう扱うかという具体的な問いのもとで再燃しました。\n\nカトリックの社会教説において、この枠組みは現在も生きています。人権を論じる際の理論的な基礎として用いられており、中世の議論が現在の政治的な文書のうちで働いている例になります。",
