    detail: "この論点は同一性言明の情報価値をめぐるものです。同じものについて語っているのに認識が増えるという事態を説明するには、指示対象だけでは足りない。この分析は、言語哲学の出発点のひとつになりました。\n\n文についても同じ区別が適用されます。文の意味は真理値であり、意義は思想だとされます。この扱いは奇妙に見えますが、複合的な表現の意味がその部分の意味から決まるという原則を保つための帰結です。\n\n後にクリプキは、固有名の意味を記述による与えられ方で説明する路線そのものを批判します。フレーゲやラッセルの立場を記述説として括り、名前は記述の束ではなく固定指示子だと論じました。この論争は現在も続いています。",
