    detail: "カントは論理学がアリストテレス以来一歩も進んでいないと書きましたが、その約百年後にこの転換が起きます。歴史の評価がいかに早く変わりうるかを示す例としてよく引かれます。\n\n三番目は心理主義で、フレーゲが厳しく批判した立場です。論理法則は思考の習慣ではなく、思考が従うべき規範だという主張で、同時期のフッサールも同じ敵と戦っていました。分析哲学と現象学は、出発点では同じ問題意識を共有していたことになります。\n\nフレーゲの狙いは算術を論理に還元することでした。しかし『算術の基本法則』第二巻の校正中に、ラッセルから体系に矛盾があるという手紙が届きます。フレーゲは付録でその事実を認めており、学問における誠実さの例として繰り返し語られる場面です。",
