    detail: "この批判はカントの区分を直撃します。分析判断と総合判断の区別を前提に、アプリオリな総合判断はいかにして可能かと問うたのがカントでした。区別そのものが揺らげば、問いの立て方も揺らぎます。\n\n全体論という帰結が出てきます。知識は周辺で経験と接し、中心に論理や数学が位置する信念の網であって、どこかで衝突が起きたときにどの部分を修正するかには選択の余地がある。極端に言えば、論理法則さえ改訂の候補になりうる、とされます。\n\n四番目はクーンの主張で、別の系譜にあります。ただし個々の観察が理論から独立でないという点で、両者の議論は響き合っており、20世紀後半の科学哲学がともに向かった方向を示しています。",
