    detail: "この主張はカントの枠組みを組み替えます。カントにおいて、必然的なものはアプリオリに知られ、経験的なものは偶然的でした。クリプキは、いかに知られるかという認識の問題と、いかにありうるかという様相の問題を切り離すべきだと論じます。\n\n逆の組み合わせも挙げられます。メートル原器の長さを一メートルと定めた人にとって、それが一メートルであることはアプリオリに知られますが、その棒が別の長さでありえた以上、偶然的です。\n\nこの区別によって、心と脳の同一性をめぐる議論にも新しい光が当たりました。もし痛みが脳状態と同一なら必然的に同一のはずだが、痛みなしに同じ脳状態がある世界は考えられるように思える。クリプキ自身がこの論法で唯物論を批判しており、心の哲学の主要な論点になっています。",
