    detail: "この構想はヒュームの帰納の問題への応答でもあります。帰納は正当化できないと認めたうえで、科学は帰納ではなく大胆な推測と反証によって進むと主張しました。問題を解決するのではなく、迂回する戦略です。\n\nポパーはこの基準によって、マルクス主義と精神分析を疑似科学と判定しました。ただし理由は同じではありません。精神分析はどんな事実が現れても説明できてしまい、はじめから何も禁じていない。マルクス主義のほうは当初は反証されうる予測を含んでいたが、予測が外れたあとに理論を救う修正が重ねられ、反証を免れるようになった、という診断です。この判定の妥当性は現在も論争の的です。\n\n境界設定の基準としては批判も多くあります。実際の科学では、予測が外れても補助的な仮説を修正して理論が守られることが常にあります。理論全体が審判に立つというクワインの全体論を踏まえると、単純な反証は成立しにくくなります。",
