    detail: "四番目との違いが重要です。ポパーにとって民主主義の要点は、最善の統治者を選ぶことではなく、悪い統治者を流血なしに交代させられることにあります。誰が統治すべきかという問いの立て方そのものを、彼は誤りだと考えました。この構えが漸次的社会工学と呼ばれます。理想像に合わせて社会を作り変えるユートピア的社会工学に対し、具体的な弊害を一つずつ取り除き、誤りを修正しながら進む方針です。\n\nこの著作は第二次大戦中にニュージーランドで書かれ、戦争への貢献だと本人が語っています。時代状況が濃く反映された論争の書であり、学術的な思想史研究としては読みが強引だという批判が繰り返しなされてきました。\n\nとりわけプラトンとヘーゲルの読解には異論が多くあります。ヘーゲルを全体主義の源流に位置づける議論は、擁護する側から強い反論を受けてきました。それでも、社会を全面的に設計する思考への警戒という論点は、いまも参照され続けています。",
