    detail: "一番目はジェイムズに近い定式で、パースはこの受け取られ方に強く反発しました。有用性を真理と同一視する方向へ流れたことを嫌い、自分の立場をプラグマティシズムと呼び直しています。この語なら誰にも盗まれまい、という皮肉が添えられていました。\n\n背景には科学の方法への信頼があります。「信念の固定化」では、固執する方法、権威による方法、理性に適うと思えるものを選ぶア・プリオリの方法、そして科学の方法が比較され、外的な実在に照らして修正されうる最後のものだけが長期的に安定すると論じられます。\n\n同時に可謬主義が説かれます。いかなる信念も誤りうるが、探究を無限に続ければ共同体は収束していく。真理をその収束点に置く考え方は、個人の有用性に真理を還元する立場とはっきり異なります。",
