    detail: "この主張は英語版が1967年にアメリカの雑誌に、フランス語版が翌1968年に発表されました。時代の気分と結びついた文章であり、権威ある起源を疑うという構えは、1969年のフーコーの作者とは何かという講演とも響き合っています。\n\n四番目のような法的な主張ではありません。テクストの意味をどこに置くかという解釈の問題であって、作者の権利を否定するものではない点は押さえておく必要があります。\n\n後の仕事では、読者の側の身体的な経験へ関心が移ります。読者的テクストと作者的テクストの区別、テクストの快楽、写真論におけるプンクトゥムなど、体系的な分析から離れて個の経験を語る方向へ進みました。この変化は、構造主義からその先への移行としても読まれます。",
