    detail: "一番目との違いが要点です。誰が誰を読んだかという事実の問題ではなく、テクストの成り立ちそのものについての主張です。作者が意識していない場合でも、テクストは先行するテクストの網目のなかにあることになります。\n\nクリステヴァはブルガリアからパリに渡り、バルトのもとで研究を始めました。バフチンの仕事が西側に知られるうえで、彼女の紹介が果たした役割は大きなものでした。\n\nこの概念も広まる過程で意味が拡散しました。単なる引用やパロディの指摘に使われることが多くなり、本来の理論的な含意が薄れているという指摘があります。有名な概念が流通するときに繰り返し起きる現象です。",
