    detail: "横断性という語は、垂直の階層と水平の同質性のどちらでもない結びつきを指します。組織のなかで固まった関係を横切る線を引くという発想で、後のドゥルーズとの共著における概念の多くがここに源をもっています。\n\nガタリはアカデミックな哲学の出身ではなく、臨床の現場の人でした。ドゥルーズとの協働が特異な生産性をもったのは、この出自の違いによるところが大きいと言われます。哲学史の内部から出てこない概念が持ち込まれたわけです。\n\n四番目の古典的精神分析への対案が、分裂分析と呼ばれる構想です。無意識を家族の劇場としてではなく、社会的で政治的な力が走る場として捉え直そうとする方向で、『アンチ・オイディプス』の中心的な主題になります。",
