    detail: "生態系という語を、自然を超えて用いるところに特徴があります。心のあり方も社会関係も、それぞれ固有の生態系をもち、単一化の圧力にさらされている。均質化していく主観性への危機感が全体を貫いています。\n\nこの構想は、資本主義が主観性そのものを生産するという分析と結びついています。何を欲しがり、何を美しいと感じるかまでが作られていく。だから抵抗もまた主観性の水準で行われねばならない、という筋道です。\n\nガタリ単独の著作は、ドゥルーズとの共著に比べて読まれる機会が少なかったのですが、環境をめぐる議論が切迫するにつれ再評価が進んでいます。生態学と政治と精神のあり方を一続きに考える枠組みとして参照されています。",
