    detail: "モースの贈与論が下敷きにあります。ポトラッチのように富を破壊してみせる慣行は、経済の合理性からは説明できません。バタイユはそこに、蓄積ではなく蕩尽こそが根本だという逆転を読み取りました。\n\n四番目のモースの議論との違いは、バタイユが連帯の維持という機能に還元しない点です。役に立つから行われるのではなく、有用性の外に出ることそのものが問題にされます。\n\nこの構想は経済学として受け入れられたわけではありません。しかし成長を前提とする経済観への根本的な異議として、消費社会論や環境をめぐる議論のなかで参照され続けています。ボードリヤールの消費社会分析にも影響が及んでいます。なお原語は économie générale で、邦訳は普遍経済のほか全般経済とも訳され、デリダの論文の題では一般経済が定訳です。文献を当たるときは訳語が一つに定まっていないことに注意してください。",
