    detail: "1930年代のコジェーヴのヘーゲル講義は、フランス思想の転換点になりました。バタイユのほかにラカン、メルロ＝ポンティ、クノー、アロンらが聴講しており、主人と奴隷の弁証法をめぐる読解がその後の展開に深い影響を残します。\n\nバタイユの立場は、体系の外に立って批判するのではありません。ヘーゲルの論理を最後まで受け止めたうえで、そこに回収されない残余を指し示すという形をとります。この身振りは脱構築の先駆として論じられてきました。\n\nデリダはバタイユ論で、この否定性を限定経済に対する一般経済として位置づけました。意味を蓄積する運動と、それを費やして無に帰す運動。両者の関係をどう考えるかが、後のフランス思想の主題のひとつになります。",
