    detail: "この概念はきわめて具体的な問題から出てきています。ガス室の存在を証言できるのは死んだ者だけだ、という論法によって証言そのものを無効化しようとする歴史修正主義の議論を、リオタールは抗争の典型として分析しました。\n\nだから相対主義とは違います。すべての立場が等価だと言っているのではなく、規則が共有されないために語りえなくなる被害が現に存在すると指摘しているのです。哲学の課題は、その語りえないものに言葉を見出すことだとされます。\n\nこの方向は、リオタール自身が最も重要と考えた仕事でした。ポストモダンの提唱者として軽やかに語られることの多い人物ですが、中心にあるのは表現を奪われた被害をどう扱うかという主題です。",
