    detail: "この区別は母的なものと父的なものという対で語られることが多く、そのために本質主義的だという批判も向けられてきました。生物学的な性と結びつけているのではないという反論もあり、評価は分かれています。\n\n詩的言語への注目が、この枠組みの実践的な帰結です。文法や意味を逸脱する言葉づかいを、単なる破壊ではなく、抑えられていた層の回帰として読む道が開かれました。\n\nアブジェクシオンの議論とも一続きです。切り離されたはずのものが完全には消えず、境界を脅かすものとして戻ってくる。言語の水準と身体の水準で、同じ構造が働いていることになります。",
