    detail: "自殺という個人的に見える現象を、社会の統合と規制の度合いという社会的な要因から説明したことが、この著作の意義とされます。統合の弱さから自己本位的、強すぎる統合から集団本位的、規制の緩みからアノミー的、規制の過剰から宿命的、という類型が立てられました。\n\n統計を用いた古典的な研究ですが、方法上の批判もあります。当時の統計の質や、宗教と自殺率の関係の解釈をめぐって、後の研究が異なる説明を提示してきました。\n\nアノミーという概念は社会学に定着し、マートンによって目標と手段の乖離という形に組み替えられ、逸脱行動の理論として展開されました。",
