    detail: "この概念の狙いは、構造主義と主意主義の両方を避けることにありました。構造が主体を決定するという見方も、個人が自由に選択するという見方も、実践の実際を捉えていない。身体に沈殿した性向という層を置くことで、両者の間を通ろうとします。\n\n文化資本という概念と組み合わせて用いられます。学歴や教養や振る舞いが、経済資本とは別の資源として働き、世代を超えて受け継がれる。学校が能力を測っているつもりで、実は出身階層を測っているのではないかという問いが、ここから出てきます。\n\n界という概念も重要です。文学や学問や政治は、それぞれ固有の賭け金とルールをもつ場であり、そこでの位置取りとして実践が理解されます。ブルデューの分析は、この三つの概念の組み合わせで進みます。",
