    detail: "一番目のような虚無的な主張ではありません。演じることが偽りだという価値判断は含まれておらず、むしろ印象の管理は社会が円滑に動くための協同作業だとされます。\n\n四番目との違いも要点です。役割に従属するのではなく、人は役割との距離をとりながら演じている。この役割距離という概念は、構造が個人を完全に規定するという見方への修正になっています。\n\nスティグマの分析も知られています。ある属性が汚点として働くとき、人はそれを隠して通過するか、公にするかという選択を迫られる。日常の細部を丹念に記述することで、大きな理論では見えない権力の働きを捉えた点が評価されています。",
