    detail: "『アサイラム』は精神病院での参与観察に基づいています。外界から遮断された場で、持ち物も名前も日課も管理されることによって、それまでの自己が剥ぎ取られていく過程が記述されました。\n\n『監獄の誕生』はその十四年後、1975年です。フーコーは特定の施設の記述ではなく、規律という権力の様式が学校や工場や軍隊にも共通して働いていることを示しました。射程の広さが違います。\n\n両者の仕事は、脱施設化の運動に理論的な支えを与えました。ただし施設の外に出た人々が地域で孤立するという別の問題も生じており、批判が現実をどう変えたかについては評価が分かれています。",
