    detail: "一番目のように、内面を読み取る手がかりとして扱うことは、まさにレヴィナスが退ける態度です。認識の対象にした時点で、他者は私の枠のうちに回収されてしまいます。\n\n責任が選択に先立つ、という主張がここから出てきます。私が引き受けると決める前に、すでに他者から呼びかけられている。だから責任は契約でも合意でもなく、逃れられないものとして描かれます。人質という激しい語まで用いられます。\n\nこの非対称性には批判もあります。無限の責任を負うという構図は、現実の相互性を捉えそこねるのではないか。またレヴィナス自身、第三者が現れるときに正義の問題が生じると論じており、二者関係だけでは社会が成り立たないことを認めています。",
