    detail: "この方向には、現象学の神学的転回という批判が向けられました。ジャニコーは、フランスの現象学が記述の学問から離れて神学へ傾いていると論じ、論争になっています。マリオン自身は、神学的な主張ではなく現象の記述の徹底だと応じています。\n\n飽和した現象という概念が中心的です。通常、直観は概念に満たない。ところが直観が概念を溢れてしまう現象がある。歴史的な出来事、絵画、自分の身体、他者の顔などが例に挙げられ、把握しきれないという経験そのものが記述の対象になります。\n\n神を存在の枠内で捉えることを偶像化とみる議論も知られています。偶像は視線をそこで止めるが、聖像は視線を無限へ送り返す。存在から神を語ることの限界を問う点で、ハイデガーの存在神論批判を引き受けています。",
