    detail: "背景にモースの贈与論があります。未開社会の贈与には返礼の義務が伴い、循環する交換の体系をなしている。この分析を受けて、では義務を伴わない贈与はありうるのかという問いが立てられました。\n\nマリオンの応答は、たとえば受け取る相手が誰か分からない寄付、二度と会わない相手への行為、あるいは受け取る側にとって誰から来たか分からない贈り物といった場面に注目します。三項が揃わないところに、交換の論理が働かない場が開ける、という論法です。\n\nバタイユの蕩尽も同じ系譜にあります。有用性の連鎖から外れる消費という主題は、経済に回収されないものを探すという点で共通しています。レヴィナスの応答としての責任も、返礼を前提としない一方向の関係として、この問題圏に属します。",
