      kind: "ai_web", label: "ウェブ照合済み",
      choicesOk: "ok",
      note: "設問へ: マルクスが経済的な資本と階級関係を軸にしたのに対し、ブルデューが文化資本や象徴資本という別種の資源を導入し、支配が正当なものとして受け入れられる仕組みを分析したという対比は資料どおりで、誤答一番目は両者を入れ替えたもの、三番目は暴力への還元、四番目は事実に反する。四択は成立している。 事実の確認: 象徴的暴力が、支配される側が支配の秩序を当然のものとして（しばしば無意識のうちに）受け入れる形で働くこと、支配的な趣味や規範の押しつけがその現れとされること、教育を通じた文化資本の測定が階層の再生産を実力主義の外観のもとで進めるという分析を確認した。 設計の記録: detail が決定論だという批判を挙げたうえで、ブルデュー自身が界の変動や複数の界のあいだの矛盾から変化の可能性を論じていることまで書き、「この論点は議論が続いています」と決着していないことも断っている。批判を挙げるだけで終わらせない書き方。 対照の記録: q345（ハビトゥス）と q346（ディスタンクシオン）が同じ概念群を扱っており、記述に食い違いはない。グラムシについては q132・q215 が扱っている（いずれも検証済み）。 確認できていない点: グラムシのヘゲモニー論と象徴的暴力が「通じます」とする対応。両概念の内容はそれぞれ確認できるが、ブルデュー自身がグラムシを踏まえたかどうかは裏づけを取れていない（detail は影響関係ではなく類比として書いており、この範囲なら成り立つ）。 選択肢の均等化（鏡像化）: 正解を対比の核だけに絞り（削った根拠は解説側に既述）、入替誤答を正解と同じ長さの鏡像に書き直し、「両者とも」型の誤答に根拠を足した。帰属が逆であることで誤りは保たれており、正解と紛れないことを確認済み。 3.04倍→1.23倍。",
