    detail: "ヒュームの共感論を受け継ぎつつ、一歩進めています。ヒュームの共感は他人の感情が伝わることでしたが、スミスは想像による立場の交換を強調し、さらに自分自身を眺める視点を導入しました。感情に基礎を置きながら偏りを免れる工夫です。\n\n『国富論』との関係は長く論じられてきました。共感を語る本と利己心を語る本が同一人物のものであることが矛盾に見えたためです。現在では矛盾しないとする見方が主流ですが、二冊が別々の領域を扱っているからではありません。利己心の追求そのものが、『道徳感情論』の描く慎慮や正義の枠のうちに置かれている、という読み方です。\n\n見えざる手という語は全著作で数回しか登場しません。またスミスは商人による独占を厳しく批判し、労働者に同情的な記述を多く残しています。市場放任の擁護者という像は、後から作られた面が強くあります。",
