    detail: "四番目のカントとの違いが要点です。カントの時間は経験を整える形式ですが、ベルクソンの持続は形式ではなく、実際に流れている当のものです。形式に整えることで失われるものを取り戻そうとする方向になります。\n\n知性と直観の対比がこれに対応します。知性は物質を切り分けて扱うのに適しているが、生命や意識を捉えるには適さない。持続に触れるには直観が要る、とされます。空間の観念が混じらない持続そのものを純粋持続と呼び、それを捉える方法が持続の直観です。この主張は非合理主義だという批判も招きました。\n\nアインシュタインとの論争が知られています。相対性理論の時間をめぐる議論で、ベルクソンは物理学の時間と生きられる時間の区別を主張しましたが、物理学の理解に誤りがあると批判され、彼の評価が下がる一因になりました。後にドゥルーズによって再評価されます。",
