    detail: "科学的な進化論としては受け入れられませんでした。生気論の一種として批判され、現代生物学の枠組みからは支持されていません。哲学的な主張としてどう評価するかは、科学の内容とは別に論じる必要があります。\n\n同時代には絶大な人気を誇りました。講演には人が詰めかけ、ノーベル文学賞も受賞しています。その後の凋落と、20世紀後半の再評価という振れ幅の大きさも、この人物の特徴です。\n\nドゥルーズによる読み直しが再評価の契機になりました。差異それ自体を考えるという主題にとって、あらかじめ与えられた同一性に従わない生成という発想が重要な資源になったためです。",
