    detail: "二人の関係は複雑です。マールブルク時代に師弟であり私的な関係もありました。ハイデガーのナチス関与の後も交流は完全には途絶えず、この事実をどう評価するかは伝記的にも思想的にも論じられ続けています。\n\nアーレントの政治理論は、ハイデガーの存在論を政治の領域へ翻訳したものだとする読みがあります。他方で、複数性の重視はハイデガーの単数的な現存在への根本的な批判だとする読みも有力です。\n\n全体主義の分析においても、この対比は生きています。人が互いから切り離されて孤立するとき、イデオロギーとテロルが入り込む余地が生まれる。複数性の破壊という診断は、公共の領域を重んじる彼女の立場と一貫しています。",
