    detail: "この主張は法実証主義への批判として提出されました。法の体系が自己完結しているという想定に対し、体系の外に決断の契機があると指摘するものです。近代の国家概念は世俗化された神学概念である、という命題もあわせて示されます。\n\n『政治的なものの概念』では、友と敵の区別が政治の固有の基準とされます。道徳の善悪や美学の美醜と並ぶ独自の対立であり、他の領域に還元できないという主張です。\n\nこの人物を扱うには、ナチスへの加担を避けて通れません。1933年に入党し、体制の法学者として振る舞い、反ユダヤ的な文章も残しました。戦後も明確な反省を示していません。それでも読まれ続けているのは、議会制民主主義の脆弱さを突く分析が、擁護する側にとっても無視できないためです。",
