    detail: "『人間本性論』は刊行当初まったく反響がなく、本人が印刷機から死んで生まれ落ちたと書き残しています。後に『人間知性研究』として書き直され、カントが読んだのはこちらのドイツ語訳が中心だったとみられています。\n\nグッドマンの新しい帰納の謎は、問題をさらに難しくしました。過去の観察と矛盾しない一般化は無数に作れるのに、なぜ特定のものだけを選ぶのか。単に事例を積み重ねるだけでは説明がつきません。\n\n現代では、ベイズ的な確率論による扱いや、最善の説明への推論という枠組みによる応答が試みられています。それでも決定的な解決には至っておらず、この批判の射程の長さが示されています。",
