    detail: "この1958年の論文が、徳倫理学の復活の起点とされます。彼女の提案は、義務ではなく人間の繁栄や徳といった概念で語り直すこと、そしてそのための心理学が整うまで道徳哲学を控えることでした。\n\n帰結主義という語も、この論文でアンスコムが批判的に命名したものです。行為の善悪を予見される結果だけで判断する立場を指し、無辜の者を殺すことすら計算次第で許容しうる点を厳しく批判しました。\n\n背景に具体的な事件があります。オックスフォード大学がトルーマンに名誉学位を授与しようとしたとき、彼女は原爆投下を無辜の者の殺害として抗議しました。抽象的な理論の話ではなく、実際の判断から出てきた批判です。ウィトゲンシュタインの弟子であり、『哲学探究』の英訳者でもあります。",
