    detail: "四番目の情動主義は、まさに批判の対象です。道徳的な主張が感情の表明にすぎないと感じられる文化が広まったこと自体を、枠組みの喪失の帰結として説明します。\n\n処方として提示されるのが、実践と物語と伝統という三つの概念です。人はある実践のうちで卓越を目指し、自分の生を一つの物語として理解し、その物語は共同体の伝統のうちに位置づけられる。徳はこの三層のうちで意味をもつとされます。\n\n自分がどんな物語の一部であるかが分からなければ、何をなすべきかも分からない、という一節が知られています。原理からの演繹ではなく、自分がどこにいるかを理解することが実践的な判断の前提になる、という主張です。",
