    detail: "この道具立てが、形而上学の復権をもたらしました。論理実証主義以降ほぼ排除されていた本質や必然性をめぐる議論が、厳密な枠組みを得て分析哲学のうちへ戻ってきます。\n\n可能世界の身分については論争があります。ルイスは、可能世界は私たちの世界と同じ意味で実在すると主張しました。多くの哲学者はこれを受け入れず、抽象的な存在や記述の集合として扱う立場を取ります。\n\n一番目の物理学における多宇宙とは別の話です。様相論理の可能世界は、あくまで論理的な可能性を扱うための道具立てであり、物理的な実在の主張とは切り離して理解する必要があります。ただしルイスの立場は、この区別を意図的に踏み越えるものでした。",
