    detail: "この批判はロックの抽象観念説に向けられています。個々の経験から共通部分を取り出して一般観念を作るという説明に対し、そんな観念は形成できないと論じました。\n\nこの論点が物質的実体の否定を支えています。知覚から独立した物質という観念も、抽象によって作られたことになっているが、そのような抽象は成り立たない。だから物質という想定も根拠を失う、という筋道です。\n\n一般性を語の働きに帰する点は、唯名論の系譜に連なります。またこの議論は、後期ウィトゲンシュタインの家族的類似とも響き合います。共通の本質を探すのではなく、語がどう使われるかを見るという方向です。",
