      note: "設問へ: どの三角形でもなく三角形一般の観念を心に思い浮かべることはできず、一般性は観念ではなく語の働きに属するという規定は『人知原理論』序論の通りで、誤答一番目は難解さの回避、三番目は有用性の否定、四番目は生得説への取り違え。四択は成立している。 事実の確認: バークリーの抽象観念批判が序論第十節以下で三つの筋（そんな観念は形成できない、必要がない、その理論は矛盾に導く）から成ること、ロックの抽象観念（色をもつが特定の色をもたない人間の観念など）を標的とすること、心は規定を欠いた観念を知覚できないという像的な立場に立つこと、そして特定の観念を他の同種のものの代表として用いるという説明を確認した。detail の要約はこの通りで、唯名論との関係も資料に見える。 対照の記録: q048（ロックの実体）、q360（存在するとは知覚されること）、q361（経験論の実体の展開）と同じ人物・主題群で、記述に食い違いはない。detail の「この論点が物質的実体の否定を支えています」という位置づけも、q360 の note と噛み合う。 確認できていない点: 後期ウィトゲンシュタインの家族的類似と「響き合います」とする関係づけの出所（両者の内容はそれぞれ確認できるが、影響関係としての裏づけは取っていない）。 選択肢の均等化: 正解の説明句を削り（解説側に既述）、誤答を型に揃えて肉付けした。四択の成立を確認済み。 2.55倍→1.19倍。",
