    detail: "伝統的知識人との対比が置かれます。聖職者や文人のように、社会の変化を超えて連続性をもつように見える層です。しかしその自律性も歴史的に形成されたものだ、という分析になります。\n\nこの概念はヘゲモニー論と一体です。支配が同意によって成り立つなら、その同意を組織する働きが要る。だから知識人の機能は、権力の維持と変革の双方において決定的だとされます。\n\n獄中で書かれた断片であり、体系的な定義が与えられているわけではありません。検閲を避けるための言い換えも含まれており、読解には注意が要ります。それでも文化と政治の関係を考える枠組みとして、広く用いられてきました。",
