    detail: "フィヒテの操作は、外部を消して内側から全体を導くというものです。ただしそれによって、なぜ自我が非我を立てるのかという新たな難問が生じます。シェリングはここに不満をもち、自然を独立した側から捉える方向へ進みました。\n\nヘーゲルの批判は、限界を語ることがすでに限界の向こうを知っていることになる、という論法です。この論法の妥当性は現在も議論されますが、体系を内側から突破する方向を決定づけました。\n\n現代の評価は一方向ではありません。カントが引いた限界の設定こそが達成だったという見方も有力で、二十世紀以降カントに立ち返る動きが何度も起きています。どちらが勝ったという話ではありません。",
