    detail: "アルチュセールの警官の呼びかけの場面は、主体が権力によって作られるという構図を鮮明に示しました。ただし、そこから出る道が示されていないという批判が繰り返されます。\n\nバトラーの応答は、パフォーマティヴィティの議論と一体です。ジェンダーが反復によって成り立つなら、反復のたびにずれが生じうる。規範の外に出るのではなく、規範の内側での引用の仕方を変えることが可能性になります。規範は反復のたびに引用され直すのであり、この引用可能性そのものがずれを生む条件になります。\n\nこの論点は、構造と主体をめぐる長い論争の現代版でもあります。フーコーの権力論にも同じ問いが向けられ、後期の自己の技術という主題がその応答として読まれています。",
