    detail: "この立場から、人格という概念が導入されます。自己意識をもち、自分の未来について選好をもてる存在を人格とし、そうでない存在と道徳的地位を区別する。この基準が、生命倫理をめぐる激しい論争を招きました。\n\nとりわけ重度の障害をもつ新生児についての議論は、障害者運動から強い抗議を受けています。講演が妨害される事態も起きており、理論の一貫性が現実の当事者にどう受け取られるかという問題を突きつけました。\n\nなおシンガー自身は2014年の『宇宙の観点から』で、選好功利主義から快楽主義的功利主義へ移ったことを明らかにしています。\n\n功利主義の徹底が直観と衝突する典型例と言えます。原則を貫くと受け入れがたい帰結が出るとき、原則を修正するのか直観を疑うのか。倫理学の方法そのものが問われる場面です。",
