    detail: "この運動には強い批判もあります。効果を測れる支援だけが評価されることで、測りにくい価値が切り捨てられるのではないか。また貧困を生む構造そのものを問わず、個人の寄付に還元してしまうという指摘もあります。\n\n身近な者を優先する感情との緊張も残ります。自分の子どもと見知らぬ子どもを同等に扱えという要求は、多くの人にとって過大です。この要求水準の高さは、功利主義に一貫して向けられてきた批判でもあります。\n\n近年、この運動をめぐっては、資金の使途や関係者の行動をめぐる問題も報じられました。理論の妥当性と運動の実際は分けて評価する必要がありますが、実践に踏み込んだ思想がどう受け止められるかを示す例になっています。",
