    detail: "この著作は行為の哲学という分野を切り開いたとされます。行為を単なる身体の運動と、それに付随する心的な原因の組み合わせとして扱う見方への批判が中心にあります。\n\n実践的知識という概念も導入されます。自分が何をしているかを、観察によらずに知っているという知の形態です。手を上げるとき、私は自分の手を見て確かめているわけではありません。\n\nこの分析は二重結果の原則の擁護にも関わります。意図した結果と、予見はしていたが意図していない副次的な結果を区別する議論です。この区別が成り立つかどうかは、医療倫理や戦争の倫理で現在も争われています。",
