    detail: "この定義によって、徳が相対的なものにならずに済みます。共同体が何を評価するかに委ねるのではなく、実践に内在する卓越性の基準に結びつけられるためです。\n\n外的善が内的善を圧迫するという分析も重要です。制度が実践を支えると同時に、報酬や地位への競争が卓越性の追求を歪めうる。大学や医療の現場で、この構図はしばしば実感されるところです。\n\nこの枠組みは、物語的統一と伝統という概念によって補われます。私は何をなすべきかに答えるには、私はどんな物語の一部かに答える必要がある。そして伝統とは、その善をめぐって歴史的に続いてきた論争として定義されます。",
