      note: "設問へ: 実践が固有の卓越性の基準をもつ協同の活動であり、内的善はその実践に参加することによってしか得られない善だという規定は『美徳なき時代』の通りで、誤答一番目は職業訓練と報酬、三番目は内面的満足、四番目は理論と応用という取り違え。四択は成立している。 事実の確認: 内的善が「当の実践に参加した経験からしか同定も認知もできない」ものとされること、マッキンタイア自身がチェスを例に用いていること、外的善（金銭・地位・権力）が実践を腐敗させうること、制度が実践を支えると同時に「腐敗させる力」をもつとされることを確認した。detail の「制度が実践を支えると同時に、報酬や地位への競争が卓越性の追求を歪めうる」はこの通り。 対照の記録: q402（『美徳なき時代』の診断）、q424（徳倫理学の系譜）、q471（物語的自己）と同じ人物で、実践・物語・伝統の三層という整理が四問で揃っている。伝統を「その善をめぐって歴史的に続いてきた論争」と定義する点も q402 の記述と食い違わない。 選択肢の均等化: 正解の説明句を削り（解説側に既述）、誤答を型に揃えて肉付けした。四択の成立を確認済み。 2.64倍→1.30倍。 選択肢の均等化: 正解の説明句を削り（解説側に既述）、誤答を型に揃えて肉付けした。四択の成立を確認済み。 1.30倍→1.27倍。",
