    detail: "アドルノらの否定弁証法は、全体を非真理として退けることで批判を徹底させました。しかしそこからは、何を目指すのかが語りにくくなります。ハーバーマスはこれを言語の合理性によって解決しましたが、形式的すぎるという批判が残りました。\n\nホネットの選択は、規範を経験のうちに探すことでした。社会的な闘争が何をめぐって起きているかを見れば、そこに承認への要求が読み取れる。理論が現実の運動と接続する道が確保されます。\n\nフレイザーとの論争では、承認だけでは経済的な不平等を扱えないという批判が向けられました。再分配と承認を別の軸として立てるべきか、承認のうちに分配も含められるか。現代の正義論の主要な争点です。",
